CREATE OR REPLACE PROCEDURE appliquer_remise(p_id IN NUMBER, p_pct IN NUMBER)
IS
BEGIN
  IF p_pct < 0 OR p_pct > 50 THEN
    RAISE_APPLICATION_ERROR(-20050, 'Remise hors plage [0, 50]');
  END IF;
  UPDATE Produit
  SET prixUnitaire = prixUnitaire * (1 - p_pct / 100)
  WHERE id = p_id;
END;

