CREATE OR REPLACE PROCEDURE top_n_clients(p_n IN NUMBER)
IS
  CURSOR c_top IS
    SELECT id, nom, prenom, caCumule
    FROM Client
    ORDER BY caCumule DESC;
  v_c c_top%ROWTYPE;
  v_count NUMBER := 0;
BEGIN
  OPEN c_top;
  LOOP
    FETCH c_top INTO v_c;
    EXIT WHEN c_top%NOTFOUND OR v_count >= p_n;
    v_count := v_count + 1;
    DBMS_OUTPUT.PUT_LINE(v_count || '. ' || v_c.nom || ' ' || v_c.prenom || ' : ' || v_c.caCumule);
  END LOOP;
  CLOSE c_top;
END;

