CREATE OR REPLACE FUNCTION safe_divide(a IN NUMBER, b IN NUMBER) RETURN NUMBER
IS
BEGIN
  RETURN a / b;
EXCEPTION
  WHEN ZERO_DIVIDE THEN
    RETURN NULL;
END;
